namespace LuminosHrm.Models;
public class AttendanceViewModel { public DateTime Date {get;set;}=DateTime.Today; public IReadOnlyList<Employee> Employees {get;set;}=Array.Empty<Employee>(); public IReadOnlyList<AttendanceRecord> Records {get;set;}=Array.Empty<AttendanceRecord>(); public int Present => Records.Count(r=>r.Status=="Present"); public int Late => Records.Count(r=>r.Status=="Late"); public int Absent => Records.Count(r=>r.Status=="Absent"); public int Remote => Records.Count(r=>r.Status=="Remote"); public AttendanceRecord RecordFor(int id)=>Records.FirstOrDefault(r=>r.EmployeeId==id) ?? new AttendanceRecord{EmployeeId=id,Date=Date}; }
